INSERT INTO FactCashBalances (SK_CustomerID, SK_AccountID, SK_DateID, BatchID, Cash) SELECT CAST(DA.SK_CustomerID AS INT) AS SK_CustomerID, CAST(DA.SK_AccountID AS INT) AS SK_AccountID, CAST(DD.SK_DateID AS INT) AS SK_DateID, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(COALESCE(SUM(CT.CT_AMT), 0) AS DECIMAL(15, 2)) AS Cash FROM Source.CashTransaction AS CT INNER JOIN DimAccount AS DA ON CT.CT_CA_ID = DA.AccountID AND DA.EffectiveDate <= CAST(CT.CT_DTS AS DATE) AND CAST(CT.CT_DTS AS DATE) < DA.EndDate INNER JOIN DimDate AS DD ON CAST(CT.CT_DTS AS DATE) = DD.DateValue GROUP BY DA.AccountID, DA.SK_CustomerID, DA.SK_AccountID, DD.SK_DateID, CAST(CT.CT_DTS AS DATE);
